# Pure-python closed-form cost estimates (no numpy available in env).
def params(d, depth, mixer="attn"):
    # MLP ratio 4 -> 8d^2 per block; attn projections 4d^2; hyena: v,eta,out projections ~3d^2 + small conv/decay params
    mlp = 8*d*d
    mx  = 4*d*d if mixer=="attn" else 3*d*d
    return (mlp+mx)*depth + 2*d*d   # + embed/unembed approx

def train_flops(N, depth, L, seq_tokens_total):
    w = 6*N*seq_tokens_total
    a = 12*depth*(L**2)*2          # fwd+bwd quadratic term per token-pair: 12*L^2*d per seq-token... computed per token below
    return w, a

def report(tag, d, depth, T, steps, bs, N=None, mixer="attn"):
    N = N or params(d,depth,mixer)
    tok = T*bs*steps
    w = 6*N*tok
    a = 12*depth*(T**2)*d*bs*steps     # attention fwd+bwd FLOPs (2 fwd + 4 bwd factor folded)
    tot = w+a
    eff = 20e12   # assumed effective FLOP/s per GPU
    print(f"{tag:34s} d={d:4d} L={T:5d} par={N/1e6:6.1f}M tok={tok/1e9:7.2f}B "
          f"FLOPs={tot/1e18:6.3f}e18 gpu-h={tot/eff/3600:8.1f}")
    return tot/eff/3600

print("== CORE TIER: training, common token budget ==")
h_core = report("A0 attn @T=512 (d384,z12)", 384,12,512,60000,64)
h_hy   = report("A1/A2 hyena @T=512 (d384,z12)", 384,12,512,60000,64,mixer="hyena")
report("A3 win-attn w=512 @T=512", 384,12,512,60000,64)
print()
print("== EXTRAPOLATION COST (eval only, train stays @T=512) ==")
def eval_gpu_h(d,depth,T,nsamp,steps_sampler,N,mixer):
    L2 = 4*depth*(T**2)*d            # fwd attention FLOPs per sample per step
    lin= 2*N*T
    per = (lin + (L2 if mixer in ("attn","win") else T*T*0.02*0 + 8*T*d*100))*steps_sampler*nsamp
    # hyena: FFT conv ~ 8*L*log2(L)*d heads ~ folded as 8*T*d*100 approximation? keep simple below
    if mixer=="hyena":
        import math
        per = (lin + 3*depth*T*math.log2(T)*d*8)*steps_sampler*nsamp
    return per/20e12/3600
for T in (512,1024,2048,4096,8192):
    ea = eval_gpu_h(384,12,T,2048,64,params(384,12,"attn"),"attn")
    eh = eval_gpu_h(384,12,T,2048,64,params(384,12,"hyena"),"hyena")
    print(f"T={T:5d}  attn eval gpu-h={ea:9.2f}   hyena eval gpu-h={eh:7.3f}   ratio={ea/max(eh,1e-9):8.1f}x")
print()
print("== DIRECT-LONG-TRAIN CONTROL (token-budget-matched: tokens/step constant) ==")
for T in (512,2048,4096,8192):
    bs = max(1, 512*64//T)          # constant tokens per step = 32768
    steps= 60000
    report(f"attn train @T={T} (bs={bs})", 384,12,T,steps,bs)
for T in (512,2048,4096,8192):
    bs = max(1, 512*64//T)
    report(f"hyena train @T={T} (bs={bs})", 384,12,T,60000,bs,mixer="hyena")
print()
print("== MEMORY: attention score tensor, per layer-sample, fp16, h=6 ==")
for T in (512,2048,4096,8192):
    print(f"  T={T:5d}: {6*T*T*2/1e9:8.3f} GB/layer-sample  (x depth without checkpointing: {12*6*T*T*2/1e9:8.2f} GB)")
print()
print("== TOTALS ==")
core = 3*(h_core+h_hy+h_core)   # A0,A1,A2,A3 x 3 seeds (A3~attn cost)
print(f"core 12 runs  ~ {core:8.1f} GPU-h")
expl = 3*report("A4/A5/A6 small d256 z8 @T=512",256,8,512,30000,64)
print(f"expl 3 runs   ~ {expl:8.1f} GPU-h ; + direct-long control 2 arms x T=4096 ~ {3*(0.55+0.11):.1f}")
EOF
